    V er2 = x0r, ei2 = x0i, sr2 = VC(0.0), si2 = VC(0.0);
    V er3 = x0r, ei3 = x0i, sr3 = VC(0.0), si3 = VC(0.0);
    V er4 = x0r, ei4 = x0i, sr4 = VC(0.0), si4 = VC(0.0);
