    { long _k = (long)13-k; yr[_k*1] = er1 - si1; yi[_k*1] = ei1 + sr1; }
    { long _k = k+1; yr[_k*1] = er2 + si2; yi[_k*1] = ei2 - sr2; }
    { long _k = (long)13-k-1; yr[_k*1] = er2 - si2; yi[_k*1] = ei2 + sr2; }
    { long _k = k+2; yr[_k*1] = er3 + si3; yi[_k*1] = ei3 - sr3; }
    { long _k = (long)13-k-2; yr[_k*1] = er3 - si3; yi[_k*1] = ei3 + sr3; }
    { long _k = k+3; yr[_k*1] = er4 + si4; yi[_k*1] = ei4 - sr4; }
    { long _k = (long)13-k-3; yr[_k*1] = er4 - si4; yi[_k*1] = ei4 + sr4; }
