      er1 += c1[j] * u_r; ei1 += c1[j] * u_i; sr1 += s1[j] * v_r; si1 += s1[j] * v_i;
      er2 += c2[j] * u_r; ei2 += c2[j] * u_i; sr2 += s2[j] * v_r; si2 += s2[j] * v_i;
      er3 += c3[j] * u_r; ei3 += c3[j] * u_i; sr3 += s3[j] * v_r; si3 += s3[j] * v_i;
