    { long _k = (long)13-k-1; V zr = er2 - si2 + cr[_k*26]; V zi = ei2 + sr2 + ci[_k*26]; V f = pw_newton(zr, zi); yr[_k*26] = zr*f; yi[_k*26] = zi*f; }
    { long _k = k+2; V zr = er3 + si3 + cr[_k*26]; V zi = ei3 - sr3 + ci[_k*26]; V f = pw_sqrtnr(zr, zi); yr[_k*26] = zr*f; yi[_k*26] = zi*f; }
    { long _k = (long)13-k-2; V zr = er3 - si3 + cr[_k*26]; V zi = ei3 + sr3 + ci[_k*26]; V f = pw_newton(zr, zi); yr[_k*26] = zr*f; yi[_k*26] = zi*f; }
    { long _k = k+3; V zr = er4 + si4 + cr[_k*26]; V zi = ei4 - sr4 + ci[_k*26]; V f = pw_sqrtnr(zr, zi); yr[_k*26] = zr*f; yi[_k*26] = zi*f; }
    { long _k = (long)13-k-3; V zr = er4 - si4 + cr[_k*26]; V zi = ei4 + sr4 + ci[_k*26]; V f = pw_newton(zr, zi); yr[_k*26] = zr*f; yi[_k*26] = zi*f; }
