    { long _k = 7; V zr = ter1 - tsi1 + cr[_k*26]; V zi = tei1 + tsr1 + ci[_k*26]; V f = pw_newton(zr, zi); yr[_k*26] = zr*f; yi[_k*26] = zi*f; }
