static V soa13_xr[2197], soa13_xi[2197], soa13_cr[2197], soa13_ci[2197];
static V soa13_or[2197], soa13_oi[2197];

static void soa13_grp(const double*restrict x0, const double*restrict c, long g0, int lanes, long m,
            double*restrict out1, double*restrict outm) {
  {
    for (long i = 0; i < 2197; i++) {
      V xr = VC(0.0), xi = VC(0.0), cr = VC(1.0), ci = VC(0.0);
      for (int l = 0; l < lanes; l++) {
        long src = 2*((g0+l)*2197 + i);
        xr[l] = x0[src]; xi[l] = x0[src+1];
        cr[l] = c[src];  ci[l] = c[src+1];
      }
      soa13_xr[i] = xr; soa13_xi[i] = xi; soa13_cr[i] = cr; soa13_ci[i] = ci;
    }
    for (long it = 0; it < m; it++) {
      for (long x = 0; x < 13; x++) {
        V *sr = soa13_xr + x*169, *si = soa13_xi + x*169;
        for (long y = 0; y < 13; y++)
          f13_z(sr + y*13, si + y*13, sr + y*13, si + y*13);
        for (long z = 0; z < 13; z++)
          f13_y(sr + z, si + z, sr + z, si + z);
      }
      for (long u = 0; u < 169; u++) {
        if (0 && (u & 7) == 0 && u + 8 < 169) {
          for (long i = 0; i < 13; i++) {
            long a = u + 8 + i*169;
            __builtin_prefetch(soa13_xr + a, 1, 3); __builtin_prefetch(soa13_xi + a, 1, 3);
            __builtin_prefetch(soa13_cr + a, 0, 3); __builtin_prefetch(soa13_ci + a, 0, 3);
          }
        }
        f13_x(soa13_xr + u, soa13_xi + u, soa13_xr + u, soa13_xi + u, soa13_cr + u, soa13_ci + u);
      }
      if (it == 0) {
        memcpy(soa13_or, soa13_xr, sizeof(soa13_or));
        memcpy(soa13_oi, soa13_xi, sizeof(soa13_oi));
      }
    }
    for (int l = 0; l < lanes; l++) {
      double *d1 = out1 + 2*(g0+l)*2197, *dm = outm + 2*(g0+l)*2197;
      for (long i = 0; i < 2197; i++) {
        d1[2*i] = soa13_or[i][l]; d1[2*i+1] = soa13_oi[i][l];
        dm[2*i] = soa13_xr[i][l]; dm[2*i+1] = soa13_xi[i][l];
      }
    }
  }
}

void run13(const double*restrict x0, const double*restrict c, long B, long m,
            double*restrict out1, double*restrict outm) {
  long done = 0;
  while (B - done >= 8) { soa13_grp(x0, c, done, 8, m, out1, outm); done += 8; }
  long rem = B - done;
  if (rem > 0) {
    if (rem >= 5)
      soa13_grp(x0, c, done, (int)rem, m, out1, outm);
    else
      for (long v = done; v < B; v++) slab13_one(x0, c, v, m, out1, outm);
  }
}
