// ---------------- L=17 : per-volume slab scheme, always-natural (P1=24, P2=408) ----------------
static V slab17_xr[867], slab17_xi[867];
static V slab17_cer[867], slab17_cei[867];
static V slab17_1r[867], slab17_1i[867];
static V slab17_tsr[72], slab17_tsi[72];
static V slab17_br[2*24], slab17_bi[2*24];

static void slab17_iter(long m) {
  for (long j = 17; j < 24; j++) { slab17_br[j] = VC(0.0); slab17_bi[j] = VC(0.0);
    slab17_br[24+j] = VC(0.0); slab17_bi[24+j] = VC(0.0); }
  for (long it = 0; it < m; it++) {
    for (long x = 0; x < 17; x++) {
      V *sr = slab17_xr + x*51, *si = slab17_xi + x*51;
      for (long cc = 0; cc < 3; cc++) {
        V *br_ = slab17_br + (cc&1)*24, *bi_ = slab17_bi + (cc&1)*24;
        f17_cb(sr + cc, si + cc, br_, bi_);
        for (long rb = 0; rb < 3; rb++) {
          V tb[8];
          tr8x8(br_ + rb*8, tb);
          for (int q = 0; q < 8; q++) slab17_tsr[(cc*8+q)*3 + rb] = tb[q];
          tr8x8(bi_ + rb*8, tb);
          for (int q = 0; q < 8; q++) slab17_tsi[(cc*8+q)*3 + rb] = tb[q];
        }
      }
      for (long cc = 0; cc < 3; cc++) {
        V *br_ = slab17_br + (cc&1)*24, *bi_ = slab17_bi + (cc&1)*24;
        f17_cb(slab17_tsr + cc, slab17_tsi + cc, br_, bi_);
        int lim = (int)(17 - cc*8); if (lim > 8) lim = 8;
        for (long rb = 0; rb < 3; rb++) {
          V tb[8];
          tr8x8(br_ + rb*8, tb);
          for (int q = 0; q < lim; q++) sr[(cc*8+q)*3 + rb] = tb[q];
          tr8x8(bi_ + rb*8, tb);
          for (int q = 0; q < lim; q++) si[(cc*8+q)*3 + rb] = tb[q];
        }
      }
    }
    for (long o = 0; o < 51; o++) {
      if (0 && (o & 7) == 0 && o + 8 < 51) {
        for (long i = 0; i < 17; i++) {
          long a = o + 8 + i*51;
          __builtin_prefetch(slab17_xr + a, 1, 3); __builtin_prefetch(slab17_xi + a, 1, 3);
          __builtin_prefetch(slab17_cer + a, 0, 3); __builtin_prefetch(slab17_cei + a, 0, 3);
        }
      }
      f17_k3(slab17_xr + o, slab17_xi + o, slab17_xr + o, slab17_xi + o,
              slab17_cer + o, slab17_cei + o);
    }
    if (it == 0) {
      memcpy(slab17_1r, slab17_xr, sizeof(slab17_1r));
      memcpy(slab17_1i, slab17_xi, sizeof(slab17_1i));
    }
  }
}

static void slab17_extract(const V*restrict ar, const V*restrict ai, double*restrict dst) {
  const double *r = (const double*)ar, *im = (const double*)ai;
  for (long x = 0; x < 17; x++)
    for (long y = 0; y < 17; y++) {
      const long rowr = x*408 + y*24;
      double *d = dst + 2*((x*17 + y)*17);
      for (long z = 0; z < 17; z++) {
        d[2*z]   = r[rowr + z];
        d[2*z+1] = im[rowr + z];
      }
    }
}

static void slab17_one(const double*restrict x0, const double*restrict c, long v, long m,
            double*restrict out1, double*restrict outm) {
  double *xr = (double*)slab17_xr, *xi = (double*)slab17_xi;
  double *cer = (double*)slab17_cer, *cei = (double*)slab17_cei;
  {
    const double *sx = x0 + 2*v*4913, *sc = c + 2*v*4913;
    for (long x = 0; x < 17; x++)
      for (long y = 0; y < 17; y++) {
        long row = x*408 + y*24;
        const double *px = sx + 2*((x*17+y)*17);
        const double *pc = sc + 2*((x*17+y)*17);
        for (long z = 0; z < 17; z++) {
          xr[row+z] = px[2*z]; xi[row+z] = px[2*z+1];
          cer[row+z] = pc[2*z]; cei[row+z] = pc[2*z+1];
        }
        for (long z = 17; z < 24; z++) {
          xr[row+z] = 0.0; xi[row+z] = 0.0;
          cer[row+z] = 1.0; cei[row+z] = 0.0;
        }
      }
    slab17_iter(m);
    slab17_extract(slab17_1r, slab17_1i, out1 + 2*v*4913);
    slab17_extract(slab17_xr, slab17_xi, outm + 2*v*4913);
  }
}

