// ---------------- L=17 : SoA across 8 volumes ----------------
static V soa17_xr[4913], soa17_xi[4913], soa17_cr[4913], soa17_ci[4913];
static V soa17_or[4913], soa17_oi[4913];

static void soa17_grp(const double*restrict x0, const double*restrict c, long g0, int lanes, long m,
            double*restrict out1, double*restrict outm) {
  {
    for (long i = 0; i < 4913; i++) {
      V xr = VC(0.0), xi = VC(0.0), cr = VC(1.0), ci = VC(0.0);
      for (int l = 0; l < lanes; l++) {
        long src = 2*((g0+l)*4913 + i);
        xr[l] = x0[src]; xi[l] = x0[src+1];
        cr[l] = c[src];  ci[l] = c[src+1];
      }
      soa17_xr[i] = xr; soa17_xi[i] = xi; soa17_cr[i] = cr; soa17_ci[i] = ci;
    }
    for (long it = 0; it < m; it++) {
      for (long x = 0; x < 17; x++) {
        V *sr = soa17_xr + x*289, *si = soa17_xi + x*289;
        for (long y = 0; y < 17; y++)
          f17_z(sr + y*17, si + y*17, sr + y*17, si + y*17);
        for (long z = 0; z < 17; z++)
          f17_y(sr + z, si + z, sr + z, si + z);
      }
      for (long u = 0; u < 289; u++) {
        if (0 && (u & 7) == 0 && u + 8 < 289) {
          for (long i = 0; i < 17; i++) {
            long a = u + 8 + i*289;
            __builtin_prefetch(soa17_xr + a, 1, 3); __builtin_prefetch(soa17_xi + a, 1, 3);
            __builtin_prefetch(soa17_cr + a, 0, 3); __builtin_prefetch(soa17_ci + a, 0, 3);
          }
        }
        f17_x(soa17_xr + u, soa17_xi + u, soa17_xr + u, soa17_xi + u, soa17_cr + u, soa17_ci + u);
      }
      if (it == 0) {
        memcpy(soa17_or, soa17_xr, sizeof(soa17_or));
        memcpy(soa17_oi, soa17_xi, sizeof(soa17_oi));
      }
    }
    for (int l = 0; l < lanes; l++) {
      double *d1 = out1 + 2*(g0+l)*4913, *dm = outm + 2*(g0+l)*4913;
      for (long i = 0; i < 4913; i++) {
        d1[2*i] = soa17_or[i][l]; d1[2*i+1] = soa17_oi[i][l];
        dm[2*i] = soa17_xr[i][l]; dm[2*i+1] = soa17_xi[i][l];
      }
    }
  }
}

void run17(const double*restrict x0, const double*restrict c, long B, long m,
            double*restrict out1, double*restrict outm) {
  long done = 0;
  while (B - done >= 8) { soa17_grp(x0, c, done, 8, m, out1, outm); done += 8; }
  long rem = B - done;
  if (rem > 0) {
    if (rem >= 5)
      soa17_grp(x0, c, done, (int)rem, m, out1, outm);
    else
      for (long v = done; v < B; v++) slab17_one(x0, c, v, m, out1, outm);
  }
}
