// ---------------- L=23 : per-volume slab scheme, always-natural (P1=24, P2=552) ----------------
static V slab23_xr[1587], slab23_xi[1587];
static V slab23_cer[1587], slab23_cei[1587];
static V slab23_1r[1587], slab23_1i[1587];
static V slab23_tsr[72], slab23_tsi[72];
static V slab23_br[2*24], slab23_bi[2*24];

static void slab23_iter(long m) {
  for (long j = 23; j < 24; j++) { slab23_br[j] = VC(0.0); slab23_bi[j] = VC(0.0);
    slab23_br[24+j] = VC(0.0); slab23_bi[24+j] = VC(0.0); }
  for (long it = 0; it < m; it++) {
    for (long x = 0; x < 23; x++) {
      V *sr = slab23_xr + x*69, *si = slab23_xi + x*69;
      for (long cc = 0; cc < 3; cc++) {
        V *br_ = slab23_br + (cc&1)*24, *bi_ = slab23_bi + (cc&1)*24;
        f23_cb(sr + cc, si + cc, br_, bi_);
        for (long rb = 0; rb < 3; rb++) {
          V tb[8];
          tr8x8(br_ + rb*8, tb);
          for (int q = 0; q < 8; q++) slab23_tsr[(cc*8+q)*3 + rb] = tb[q];
          tr8x8(bi_ + rb*8, tb);
          for (int q = 0; q < 8; q++) slab23_tsi[(cc*8+q)*3 + rb] = tb[q];
        }
      }
      for (long cc = 0; cc < 3; cc++) {
        V *br_ = slab23_br + (cc&1)*24, *bi_ = slab23_bi + (cc&1)*24;
        f23_cb(slab23_tsr + cc, slab23_tsi + cc, br_, bi_);
        int lim = (int)(23 - cc*8); if (lim > 8) lim = 8;
        for (long rb = 0; rb < 3; rb++) {
          V tb[8];
          tr8x8(br_ + rb*8, tb);
          for (int q = 0; q < lim; q++) sr[(cc*8+q)*3 + rb] = tb[q];
          tr8x8(bi_ + rb*8, tb);
          for (int q = 0; q < lim; q++) si[(cc*8+q)*3 + rb] = tb[q];
        }
      }
    }
    for (long o = 0; o < 69; o++) {
      if (0 && (o & 7) == 0 && o + 8 < 69) {
        for (long i = 0; i < 23; i++) {
          long a = o + 8 + i*69;
          __builtin_prefetch(slab23_xr + a, 1, 3); __builtin_prefetch(slab23_xi + a, 1, 3);
          __builtin_prefetch(slab23_cer + a, 0, 3); __builtin_prefetch(slab23_cei + a, 0, 3);
        }
      }
      f23_k3(slab23_xr + o, slab23_xi + o, slab23_xr + o, slab23_xi + o,
              slab23_cer + o, slab23_cei + o);
    }
    if (it == 0) {
      memcpy(slab23_1r, slab23_xr, sizeof(slab23_1r));
      memcpy(slab23_1i, slab23_xi, sizeof(slab23_1i));
    }
  }
}

static void slab23_extract(const V*restrict ar, const V*restrict ai, double*restrict dst) {
  const double *r = (const double*)ar, *im = (const double*)ai;
  for (long x = 0; x < 23; x++)
    for (long y = 0; y < 23; y++) {
      const long rowr = x*552 + y*24;
      double *d = dst + 2*((x*23 + y)*23);
      for (long z = 0; z < 23; z++) {
        d[2*z]   = r[rowr + z];
        d[2*z+1] = im[rowr + z];
      }
    }
}

static void slab23_one(const double*restrict x0, const double*restrict c, long v, long m,
            double*restrict out1, double*restrict outm) {
  double *xr = (double*)slab23_xr, *xi = (double*)slab23_xi;
  double *cer = (double*)slab23_cer, *cei = (double*)slab23_cei;
  {
    const double *sx = x0 + 2*v*12167, *sc = c + 2*v*12167;
    for (long x = 0; x < 23; x++)
      for (long y = 0; y < 23; y++) {
        long row = x*552 + y*24;
        const double *px = sx + 2*((x*23+y)*23);
        const double *pc = sc + 2*((x*23+y)*23);
        for (long z = 0; z < 23; z++) {
          xr[row+z] = px[2*z]; xi[row+z] = px[2*z+1];
          cer[row+z] = pc[2*z]; cei[row+z] = pc[2*z+1];
        }
        for (long z = 23; z < 24; z++) {
          xr[row+z] = 0.0; xi[row+z] = 0.0;
          cer[row+z] = 1.0; cei[row+z] = 0.0;
        }
      }
    slab23_iter(m);
    slab23_extract(slab23_1r, slab23_1i, out1 + 2*v*12167);
    slab23_extract(slab23_xr, slab23_xi, outm + 2*v*12167);
  }
}

