static void slab36_extract(const V*restrict ar, const V*restrict ai, double*restrict dst) {
  const double *r = (const double*)ar, *im = (const double*)ai;
  for (long x = 0; x < 36; x++)
    for (long y = 0; y < 36; y++) {
      const long rowr = x*1440 + y*40;
      double *d = dst + 2*((x*36 + y)*36);
      for (long z = 0; z < 36; z++) {
        d[2*z]   = r[rowr + z];
        d[2*z+1] = im[rowr + z];
      }
    }
}

