static void slab45x_extract(const V*restrict ar, const V*restrict ai, double*restrict dst) {
  const double *r = (const double*)ar, *im = (const double*)ai;
  for (long x = 0; x < 45; x++)
    for (long y = 0; y < 45; y++) {
      const long rowr = x*2160 + y*48;
      double *d = dst + 2*((x*45 + y)*45);
      for (long z = 0; z < 45; z++) {
        d[2*z]   = r[rowr + z];
        d[2*z+1] = im[rowr + z];
      }
    }
}


