void run45(const double*restrict x0, const double*restrict c, long B, long m,
           double*restrict out1, double*restrict outm) {
  for (long j = 45; j < 48; j++) { a245_buf_r[j] = VC(0.0); a245_buf_i[j] = VC(0.0);
    a245_buf_r[48+j] = VC(0.0); a245_buf_i[48+j] = VC(0.0); }
  double *xr = (double*)a245_dr, *xi = (double*)a245_di;
  double *cer = (double*)a245_cer, *cei = (double*)a245_cei;
  double *cor = (double*)a245_cor, *coi = (double*)a245_coi;
  double *cer1 = (double*)a245_cer1, *cei1 = (double*)a245_cei1; double *cor1 = (double*)a245_cor1, *coi1 = (double*)a245_coi1;
  for (long v = 0; v < B; v++) {
    const double *sx = x0 + 2*v*91125, *sc = c + 2*v*91125;
    for (long x = 0; x < 45; x++) {
      long k1 = x % 9, k2 = x % 5;
      long xce = 5*k1 + k2;    // even-sweep c slot for logical slab x
      long xco = 9*k2 + k1;    // odd-sweep  c slot for logical slab x
      for (long y = 0; y < 45; y++) {
        long row = x*2160 + y*48;
        long rowe = xce*2160 + y*48, rowo = xco*2160 + y*48;
        const double *px = sx + 2*((x*45+y)*45);
        const double *pc = sc + 2*((x*45+y)*45);
        for (long z = 0; z < 45; z++) {
          xr[row+z] = px[2*z]; xi[row+z] = px[2*z+1];
          cer[rowe+z] = pc[2*z]; cei[rowe+z] = pc[2*z+1];
          cor[rowo+z] = pc[2*z]; coi[rowo+z] = pc[2*z+1];
          cer1[xce*2160 + z*48 + y] = pc[2*z]; cei1[xce*2160 + z*48 + y] = pc[2*z+1]; cor1[xco*2160 + z*48 + y] = pc[2*z]; coi1[xco*2160 + z*48 + y] = pc[2*z+1];
        }
        for (long z = 45; z < 48; z++) {
          xr[row+z] = 0.0; xi[row+z] = 0.0;
          cer[rowe+z] = 1.0; cei[rowe+z] = 0.0;
          cor[rowo+z] = 1.0; coi[rowo+z] = 0.0;
          cer1[rowe+z] = 1.0; cei1[rowe+z] = 0.0; cor1[rowo+z] = 1.0; coi1[rowo+z] = 0.0;
        }
      }
    }
    // prologue
    for (long s = 0; s < 45; s++)
      a245_yz(a245_dr + s*270, a245_di + s*270);
    for (long b = 0; b < 5; b++)
      f45o_s1(a245_dr, a245_di, a245_sr + b*270, a245_si + b*270, a245_idxp + 9*b);
    for (long t = 0; t < m-1; t++) {
      if ((t & 1) == 0) {
        for (long k1 = 0; k1 < 9; k1++) {
          const V *ecr = ((t+1) & 1) ? a245_cer1 : a245_cer, *eci = ((t+1) & 1) ? a245_cei1 : a245_cei;
          f45e_s2(a245_sr + 5*k1*270, a245_si + 5*k1*270, ecr + 5*k1*270, eci + 5*k1*270,
                  a245_tr, a245_ti, 0, 270);
          if (t == 0) {
            for (long k2 = 0; k2 < 5; k2++) {
              long dst = (long)a245_crt[k1*5+k2];
              memcpy(a245_1r + dst*270, a245_tr + k2*270, 270*sizeof(V));
              memcpy(a245_1i + dst*270, a245_ti + k2*270, 270*sizeof(V));
            }
          }
          for (long k2 = 0; k2 < 5; k2++)
            a245_yz(a245_tr + k2*270, a245_ti + k2*270);
          f45e_s1(a245_tr, a245_ti, a245_dr + ((2*k1) % 9)*270, a245_di + ((2*k1) % 9)*270, a245_tin5);
        }
      } else {
        for (long k1p = 0; k1p < 5; k1p++) {
          const V *ocr = ((t+1) & 1) ? a245_cor1 : a245_cor, *oci = ((t+1) & 1) ? a245_coi1 : a245_coi;
          f45o_s2(a245_dr + 9*k1p*270, a245_di + 9*k1p*270, ocr + 9*k1p*270, oci + 9*k1p*270,
                  a245_tr, a245_ti, 0, 270);
          for (long kq = 0; kq < 9; kq++)
            a245_yz(a245_tr + kq*270, a245_ti + kq*270);
          f45o_s1(a245_tr, a245_ti, a245_sr + ((4*k1p) % 5)*270, a245_si + ((4*k1p) % 5)*270, a245_tin9);
        }
      }
    }
    // epilogue for iteration m-1
    V *fr, *fi;
    if (((m-1) & 1) == 0) {
      fr = a245_dr; fi = a245_di;
      const V *ecr = (m & 1) ? a245_cer1 : a245_cer, *eci = (m & 1) ? a245_cei1 : a245_cei;
      for (long k1 = 0; k1 < 9; k1++) {
        f45e_s2(a245_sr + 5*k1*270, a245_si + 5*k1*270, ecr + 5*k1*270, eci + 5*k1*270,
                a245_tr, a245_ti, 0, 270);
        for (long k2 = 0; k2 < 5; k2++) {
          long dst = (long)a245_crt[k1*5+k2];
          memcpy(fr + dst*270, a245_tr + k2*270, 270*sizeof(V));
          memcpy(fi + dst*270, a245_ti + k2*270, 270*sizeof(V));
        }
      }
    } else {
      fr = a245_sr; fi = a245_si;
      const V *ocr = (m & 1) ? a245_cor1 : a245_cor, *oci = (m & 1) ? a245_coi1 : a245_coi;
      for (long k1p = 0; k1p < 5; k1p++) {
        f45o_s2(a245_dr + 9*k1p*270, a245_di + 9*k1p*270, ocr + 9*k1p*270, oci + 9*k1p*270,
                a245_tr, a245_ti, 0, 270);
        for (long kq = 0; kq < 9; kq++) {
          long dst = (long)a245_crt[kq*5+k1p];
          memcpy(fr + dst*270, a245_tr + kq*270, 270*sizeof(V));
          memcpy(fi + dst*270, a245_ti + kq*270, 270*sizeof(V));
        }
      }
    }
    slab45x_extractp(m > 1 ? a245_1r : fr, m > 1 ? a245_1i : fi, out1 + 2*v*91125, 1);
    slab45x_extractp(fr, fi, outm + 2*v*91125, (int)(m & 1));
  }
}

