static void sq64_yz(V* sr, V* si) {
  for (long y = 0; y < 64; y++)
    f64_zline(sr + y*8, si + y*8);
  for (long cc = 0; cc < 8; cc++)
    f64_ycol(sr + cc, si + cc, sr + cc, si + cc);
}
#define SQ64_YZ_DEFINED

// ---------------- L=64 : square-CT fused ping-pong (G=8, P1=64, P2=4104) ----------------
static V sq64_ar[32832], sq64_ai[32832];
static V sq64_br[32832], sq64_bi[32832];
static V sq64_cr[32832], sq64_ci[32832];

static V sq64_1r[32832], sq64_1i[32832];
static V sq64_tr[8208], sq64_ti[8208];
static V sq64_buf_r[2*64], sq64_buf_i[2*64];

#ifndef SQ64_YZ_DEFINED
static void sq64_yz(V* sr, V* si) {
  for (long cc = 0; cc < 8; cc++) {
    V *br_ = sq64_buf_r + (cc&1)*64, *bi_ = sq64_buf_i + (cc&1)*64;
    f64_cb(sr + cc, si + cc, br_, bi_);
    for (long rb = 0; rb < 8; rb++) {
      V tb[8];
      tr8x8(br_ + rb*8, tb);
      for (int q = 0; q < 8; q++) slabts64_r[(cc*8+q)*8 + rb] = tb[q];
      tr8x8(bi_ + rb*8, tb);
      for (int q = 0; q < 8; q++) slabts64_i[(cc*8+q)*8 + rb] = tb[q];
    }
  }
  for (long cc = 0; cc < 8; cc++) {{
    V *br_ = sq64_buf_r + (cc&1)*64, *bi_ = sq64_buf_i + (cc&1)*64;
    f64_cb(slabts64_r + cc, slabts64_i + cc, br_, bi_);
    int lim = (int)(64 - cc*8); if (lim > 8) lim = 8;
    for (long rb = 0; rb < 8; rb++) {{
      V tb[8];
      tr8x8(br_ + rb*8, tb);
      for (int q = 0; q < lim; q++) sr[(cc*8+q)*8 + rb] = tb[q];
      tr8x8(bi_ + rb*8, tb);
      for (int q = 0; q < lim; q++) si[(cc*8+q)*8 + rb] = tb[q];
    }}
  }}
}
#endif
#undef SQ64_YZ_DEFINED

void run64(const double*restrict x0, const double*restrict c, long B, long m,
            double*restrict out1, double*restrict outm) {
  for (long j = 64; j < 64; j++) { sq64_buf_r[j] = VC(0.0); sq64_buf_i[j] = VC(0.0);
    sq64_buf_r[64+j] = VC(0.0); sq64_buf_i[64+j] = VC(0.0); }
  double *xr = (double*)sq64_ar, *xi = (double*)sq64_ai;
  double *cr = (double*)sq64_cr, *ci = (double*)sq64_ci;
  
  for (long v = 0; v < B; v++) {
    const double *sx = x0 + 2*v*262144, *sc = c + 2*v*262144;
    for (long x = 0; x < 64; x++) {
      long xc = (x % 8)*8 + (x / 8);   // c permuted: phys G*g+k2 holds logical G*k2+g
      for (long y = 0; y < 64; y++) {
        long row = x*4104 + y*64;
        long rowc = xc*4104 + y*64;
        const double *px = sx + 2*((x*64+y)*64);
        const double *pc = sc + 2*((x*64+y)*64);
        for (long z = 0; z < 64; z++) {
          xr[row+z] = px[2*z]; xi[row+z] = px[2*z+1];
          cr[rowc+z] = pc[2*z]; ci[rowc+z] = pc[2*z+1];
          
        }
        for (long z = 64; z < 64; z++) {
          xr[row+z] = 0.0; xi[row+z] = 0.0;
          cr[rowc+z] = 1.0; ci[rowc+z] = 0.0;
          
        }
      }
    }
    // prologue: yz on all slabs (natural), then stage1 cosets (strided) -> B
    for (long s = 0; s < 64; s++)
      sq64_yz(sq64_ar + s*513, sq64_ai + s*513);
    for (long s = 0; s < 8; s++)
      f64_s1p(sq64_ar + s*513, sq64_ai + s*513, sq64_br + s*513, sq64_bi + s*513,
               sq64_twr + s*8, sq64_twi + s*8);
    V *srcr = sq64_br, *srci = sq64_bi, *dstr = sq64_ar, *dsti = sq64_ai;
    V *TAr = sq64_tr, *TAi = sq64_ti, *TBr = sq64_tr + 4104, *TBi = sq64_ti + 4104;
    for (long t = 0; t < m-1; t++) {
      for (long g = 0; g < 8; g++) {
        const V *pwcr = sq64_cr;
        const V *pwci = sq64_ci;
        if (0 && t > 0) {{
          f64_s2z(srcr + g*8*513, srci + g*8*513, pwcr + g*8*513, pwci + g*8*513, TAr, TAi);
          for (long k2 = 0; k2 < 8; k2++)
            for (long cc = 0; cc < 8; cc++)
              f64_ycol(TAr + k2*513 + cc, TAi + k2*513 + cc, TAr + k2*513 + cc, TAi + k2*513 + cc);
        }} else {{
          f64_s2(srcr + g*8*513, srci + g*8*513, pwcr + g*8*513, pwci + g*8*513,
                  TAr, TAi, 0, 512);
          if (t == 0) {{
            for (long k2 = 0; k2 < 8; k2++) {{
              memcpy(sq64_1r + (8*k2+g)*513, TAr + k2*513, 513*sizeof(V));
              memcpy(sq64_1i + (8*k2+g)*513, TAi + k2*513, 513*sizeof(V));
            }}
          }}
          for (long k2 = 0; k2 < 8; k2++)
            sq64_yz(TAr + k2*513, TAi + k2*513);
        }}
        f64_s1(TAr, TAi, dstr + g*513, dsti + g*513, sq64_twr + g*8, sq64_twi + g*8);
      }
      V *tmp;
      tmp = srcr; srcr = dstr; dstr = tmp;
      tmp = srci; srci = dsti; dsti = tmp;
    }
    // epilogue: stage2 + pw -> natural into dst
    for (long g = 0; g < 8; g++)
      f64_s2e(srcr + g*8*513, srci + g*8*513,
               sq64_cr + g*8*513,
               sq64_ci + g*8*513,
               dstr + g*513, dsti + g*513, 0, 512);
    slab64_extract(m > 1 ? sq64_1r : dstr, m > 1 ? sq64_1i : dsti, out1 + 2*v*262144);
    slab64_extract(dstr, dsti, outm + 2*v*262144);
  }
}

